from pathlib import Path
import json
D=Path(__file__).resolve().parent
def ru(v,n=2):return f'{v:,.{n}f}'.replace(',',' ').replace('.',',')
def score(z):return f"{ru(z['delta']*100)} [{ru(z['ci'][0]*100)}; {ru(z['ci'][1]*100)}]"
def load(s):return json.loads((D/s).read_bytes())
def main():
    data=load('results.json')
    native=load('native-validation.json')
    names={'proposed':'Частота × стоимость','cost':'Только стоимость','lru':'LRU','lru_costhot':'LRU со стоимостным порядком записи','gdsf':'Пакетный GDSF','s3':'S3-FIFO','s3_costhot':'S3-FIFO со стоимостным порядком записи','sieve':'SIEVE','sieve_costhot':'SIEVE со стоимостным порядком записи'}
    text=['# S3-FIFO и SIEVE на последовательностях обращений к памяти SERBench',
    'При одинаковом доступе к текущему пакету и лимите 31 вектор проверка подтвердила преимущество политики «частота × стоимость» по числу сохранённых токенов. На 179 состояниях переноса добавочная экономия составила **0,53 п.п.** относительно S3-FIFO и **0,50 п.п.** относительно SIEVE. Измеренное преимущество сократилось примерно в десять раз после того, как обе опубликованные политики получили тот же порядок записи, учитывающий стоимость. Результат относится к бюджетированию чтения готового пула доказательств. [Предварительный протокол](PROTOCOL_RU.md)',
    'Первая панель включает все 305 состояний на 103 репозиториях из R48, вторая — 179 состояний из 68 других репозиториев. На каждое состояние подаётся только история того же запуска со строго более коротким совпадающим префиксом событий. Доли экономии рассчитаны на всех входных токенах, включая текст самого запроса и дубли; общая дедупликация внутри пакета исключена из выигрыша. Парные 95% интервалы получены по целым репозиториям с 20 000 перевыборок отдельно для каждой панели. Числа в квадратных скобках — границы отдельных контрастов. История этих двух панелей уже использовалась при оценке стоимости предыдущих методов. [Аппаратный опыт R49](../long_gpu/REPORT_RU.md) · [Базовый опыт R48](../../graph_memory_round48/cache_admission/REPORT_RU.md)',
    '## Пакетный интерфейс',
    'Все векторы, имевшиеся перед текущим запросом, можно использовать до выселения. При стоимостном порядке записи сначала обрабатываются промахи, затем попадания; внутри обеих групп более дорогие фрагменты обрабатываются позже. Пользовательская выдача опирается на один и тот же исходный снимок у всех методов. В таблице абсолютная экономия и попадания относятся к межзапросному повторному использованию, разница — добавочные проценты исходных токенов относительно соответствующей строки.']
    for p in ['R48','R49']:
        panel=data[p];v=panel['conditions']['batch'];text.append('### '+p+' · '+str(panel['states'])+' состояний')
        rows=['| Политика записи | Попадания | Сохранено токенов | Осталось кодировать | Выигрыш исследуемой политики, п.п. [95% ДИ] |','|---|---:|---:|---:|---:|']
        for k in ['proposed','cost','gdsf','lru_costhot','s3','s3_costhot','sieve','sieve_costhot']:
            z=v[k];rows.append(f"| {names[k]} | {ru(z['hits'],0)} | {ru(z['saved'],0)} | {ru(z['net'],0)} | {score(z) if k!='proposed' else '—'} |")
        text.append('\n'.join(rows))
    text+=['## Пообъектный интерфейс',
        'Для этого контроля каждая политика получает по одному уникальному ключу текущего пакета за раз. Поток имитирует сериализацию списка кандидатов; фактической временной метки чтения отдельного кандидата в SERBench нет. Этот порядок вытесняет почти все повторяющиеся объекты до обращения к ним. При обратном порядке наблюдалось то же явление. Высокий выигрыш при сериализации нельзя переносить на обслуживание готовых пакетов.']
    rows=['| Панель | Порядок | Политика | Попадания | Сохранено токенов | Выигрыш исследуемой политики, п.п. [95% ДИ] |','|---|---|---|---:|---:|---:|']
    for p,v in data.items():
        for field,label in [('stream','Исходный'),('stream_reverse','Обратный')]:
            for k in ['proposed','lru','s3','sieve']:
                z=v['conditions'][field][k];rows.append(f"| {p} | {label} | {names[k]} | {ru(z['hits'],0)} | {ru(z['saved'],0)} | {score(z) if k!='proposed' else '—'} |")
    text+=['\n'.join(rows), '## Проверка и ограничения',
      'В исходной и обратной сериализации SIEVE и LRU получили ноль попаданий на обеих панелях. У S3-FIFO сохранились отдельные попадания. На пакетном интерфейсе стоимостной вариант SIEVE дал те же агрегированные расходы, что сильный LRU; предпочтение кандидатов с высокой стоимостью почти полностью устранило межалгоритмический разрыв. В этих коротких историях исследуемая политика также чаще попадала по числу документов. Гипотеза о возможном обмене между числом попаданий и их ценой на этих панелях поддержки не получила. [Все результаты и макросредние](results.json)',
      'Оригинальная библиотека libCacheSim в ревизии 5fa68ef была собрана в WSL. Референсный драйвер вызывал исходные функции C. На девяти синтетических потоках весь вектор попаданий совпал для каждой политики, 22 344 обращения на алгоритм. Дополнительная сверка на SERBench повторила 3 872 оценки политики и состояния в авторской библиотеке, включая чтения до обновления и стоимостной порядок. Пакетные правила относятся к адаптеру этого исследования. Оригинальные статьи изучали веб-кеши и другие рабочие нагрузки. [Нативная сверка](native-validation.json) · [Синтетическая сверка](reference.json) · [Статья о S3-FIFO](https://junchengyang.com/publication/sosp23-s3fifo.pdf) · [Статья о SIEVE](https://www.usenix.org/conference/nsdi24/presentation/zhang-yazhuo)',
      'Предел 512 КиБ включает 31 вектор (507 904 байта полезных значений), до 64 байт метаданных на слот и 256 байт заголовка. Для описанного packed-представления S3-FIFO добавляем ещё 1 080 байт под 27 ghost-записей; всего до 511 224 байт. Для исследуемой политики суммарно до 511 168 с 1 024 байтами эскиза. В SIEVE достаточно указателя в заголовке и бита в записи. Счётчики модулей C работают на unit-size запросах; их внутреннее аллоцирование и память интерпретатора отдельно не профилировались. Показатель здесь — объём избегаемого кодирования. Аппаратное время SIEVE и S3-FIFO в этом контроле ещё не измерено. [Инструкция и схема проверки](REPRODUCE_RU.md)']
    (D/'REPORT_RU.md').write_text('\n\n'.join(text)+'\n',encoding='utf-8')
if __name__=='__main__':main()

